const item = $input.first();
const binKeys = Object.keys(item.binary || {});
let parsed;
let fileName = '';
if (binKeys.length > 0) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, binKeys[0]);
  let text = buffer.toString('utf8');
  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
  parsed = JSON.parse(text);
  fileName = item.binary[binKeys[0]].fileName || '';
} else if (item.json.conteudo_json) {
  const raw = item.json.conteudo_json;
  parsed = typeof raw === 'string' ? JSON.parse(raw.replace(/^﻿/, '')) : raw;
  fileName = 'conteudo_colado';
} else {
  throw new Error('Nenhum arquivo ou conteúdo JSON foi enviado no formulário.');
}
const branches = Array.isArray(parsed) ? parsed : (parsed.data || []);
if (!Array.isArray(branches) || branches.length === 0) {
  throw new Error('O arquivo não contém nenhuma agência na lista "data". Nada foi alterado.');
}
return [{ json: { branches: branches, fileName: fileName } }];

const branches = $('Parse Branches File').first().json.branches;
const nowIso = new Date().toISOString();

function keyOf(b) {
  const cnpj = (b.participant && b.participant.cnpjNumber) || '';
  const code = (b.identification && b.identification.code) || '';
  return cnpj + '-' + code;
}

const rows = [];
const currentKeys = new Set();
for (const b of branches) {
  const key = keyOf(b);
  if (currentKeys.has(key)) continue;
  currentKeys.add(key);
  rows.push({
    branch_key: key,
    branch_name: (b.identification && b.identification.name) || '',
    town: ((b.postalAddress && b.postalAddress.townName) || '') + '/' + ((b.postalAddress && b.postalAddress.countrySubDivision) || ''),
    branch_json: JSON.stringify(b),
    last_seen: nowIso,
  });
}

const previous = $input.all().map(i => i.json).filter(r => r && r.branch_key);
const removed = [];
for (const r of previous) {
  if (!currentKeys.has(r.branch_key)) {
    let obj = null;
    try { obj = JSON.parse(r.branch_json); } catch (e) { obj = { raw: r.branch_json }; }
    removed.push(obj);
  }
}

function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

let html = '<h2>Oportunidade de negócio: abertura de agência física da fintech</h2>';
html += '<p>Na comparação entre o arquivo anterior e o atual, ' + removed.length + ' agência(s) Santander deixaram de constar na lista. ';
html += 'As regiões abaixo podem representar uma oportunidade para abertura de agência física da fintech.</p>';
for (const b of removed) {
  const id = b.identification || {};
  const addr = b.postalAddress || {};
  html += '<hr><h3>Agência ' + esc(id.code || '') + ' - ' + esc(id.name || '') + '</h3>';
  html += '<p>' + esc(addr.address || '') + ', ' + esc(addr.districtName || '') + ' - ' + esc(addr.townName || '') + '/' + esc(addr.countrySubDivision || '') + ' - CEP ' + esc(addr.postCode || '') + '</p>';
  html += '<p><b>Objeto completo da agência:</b></p>';
  html += '<pre style="background:#f4f4f4;padding:8px;font-size:12px;">' + esc(JSON.stringify(b, null, 2)) + '</pre>';
}

return [{ json: {
  previousCount: previous.length,
  currentCount: rows.length,
  removedCount: removed.length,
  removed: removed,
  emailHtml: html,
  rows: rows,
} }];
